<script setup lang="ts">
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import type { InitializePayload } from '../api/types'
import { useGameStore } from '../stores/game'

const router = useRouter(); const game = useGameStore()
const form = reactive({ gameId: `grey-${Math.random().toString(36).slice(2, 8)}`, name: '', description: '', location: '', region: '', weather: '', season: '', time: '', mainQuest: '', originScene: '', characterName: '旅人', age: 16, gender: '未定', archetype: 'swordsman', difficulty: 'adventure' })
const error = ref(''); const step = ref(1)
const regions = [['forest', '密林'], ['plains', '开阔草原'], ['mountain', '山脉地带'], ['dungeon', '地窟'], ['swamp', '沼泽'], ['ruins', '废墟'], ['cavern', '洞窟群'], ['town', '城镇'], ['corrupted_land', '侵蚀之地'], ['volcanic', '火山带']]
const difficultyNames: Record<string, string> = { story: '剧情', adventure: '冒险', hard: '艰难' }
const archetypes = [{ id: 'swordsman', name: '剑士', text: '稳健近战，生命与力量均衡。' }, { id: 'mage', name: '法师', text: '高智力和精神，适合施法。' }, { id: 'ranger', name: '游侠', text: '敏捷灵活，擅长在荒野行动。' }, { id: 'alchemist', name: '炼金术士', text: '资源与精神更充裕，适合准备型玩法。' }]
function nullable(value: string): string | null { const text = value.trim(); return text || null }
function payload(): InitializePayload { return { worldId: 'isekai_grey', name: nullable(form.name), description: nullable(form.description), location: nullable(form.location), region: nullable(form.region), weather: nullable(form.weather), season: nullable(form.season), time: nullable(form.time), mainQuest: nullable(form.mainQuest), originScene: nullable(form.originScene), characterName: form.characterName.trim() || '旅人', age: Math.max(1, Math.min(120, Number(form.age) || 16)), gender: form.gender, archetype: form.archetype, difficulty: form.difficulty } }
function next() { if (step.value === 1 && !form.gameId.trim()) { error.value = '游戏 ID 不能为空。'; return } if (step.value === 2 && !form.characterName.trim()) { error.value = '角色名不能为空。'; return } error.value = ''; step.value = Math.min(3, step.value + 1) }
async function submit() { if (!/^[A-Za-z0-9_-]{1,80}$/.test(form.gameId.trim())) { error.value = '游戏 ID 只能包含字母、数字、下划线和短横线。'; step.value = 1; return } error.value = ''; try { await game.initialize(form.gameId.trim(), payload()); await router.push(`/play/${encodeURIComponent(form.gameId.trim())}`) } catch (cause) { error.value = cause instanceof Error ? cause.message : '初始化失败。' } }
</script>

<template>
  <section class="create-page page-content">
    <div class="section-heading"><div><p class="eyebrow">CREATE / {{ String(step).padStart(2, '0') }}</p><h1>建立一局新的灰境远征</h1><p class="lede">决定旅人第一次醒来时，看到的世界与身份。</p></div><button class="quiet-button" type="button" @click="router.push('/')">返回游戏桌</button></div>
    <div class="progress-rail" aria-label="创建进度"><button v-for="item in [{n:1,t:'世界'}, {n:2,t:'角色'}, {n:3,t:'确认'}]" :key="item.n" type="button" :class="{ current: step === item.n, complete: step > item.n }" @click="item.n < step ? step = item.n : undefined"><span>{{ item.n }}</span>{{ item.t }}</button></div>
    <form class="form-layout" @submit.prevent="step < 3 ? next() : submit()">
      <section v-if="step === 1" class="form-panel"><div class="panel-heading"><span class="panel-kicker">WORLD DEFINITION</span><h2>先决定这场故事从哪里开始</h2></div><div class="form-grid"><label class="field wide"><span>游戏 ID <em>必填</em></span><input v-model="form.gameId" maxlength="80" required /><small>用于存档路径，也会出现在浏览器地址中。</small></label><label class="field"><span>世界</span><input value="isekai_grey · 灰境" readonly /></label><label class="field"><span>开场地点</span><input v-model="form.location" placeholder="例如：边境驿站" /></label><label class="field"><span>区域</span><select v-model="form.region"><option value="">由世界决定</option><option v-for="[id, label] in regions" :key="id" :value="id">{{ label }}</option></select></label><label class="field"><span>时间</span><input v-model="form.time" placeholder="留空使用默认值" /></label><label class="field"><span>天气</span><input v-model="form.weather" placeholder="例如：阴冷" /></label><label class="field"><span>季节</span><input v-model="form.season" placeholder="例如：深秋" /></label><label class="field wide"><span>世界名称</span><input v-model="form.name" placeholder="留空由叙事层命名" /></label><label class="field wide"><span>世界描述</span><textarea v-model="form.description" rows="3" placeholder="你希望玩家初见这个世界时感受到什么？" /></label><label class="field wide"><span>主线方向</span><input v-model="form.mainQuest" placeholder="例如：查明裂隙为何再次苏醒" /></label><label class="field wide"><span>开场场景</span><textarea v-model="form.originScene" rows="4" placeholder="可选。描述角色进入故事的第一个画面。" /></label></div></section>
      <section v-else-if="step === 2" class="form-panel"><div class="panel-heading"><span class="panel-kicker">AP CHARACTER</span><h2>把一个人放进世界里</h2></div><div class="form-grid"><label class="field"><span>角色名 <em>必填</em></span><input v-model="form.characterName" maxlength="80" required /></label><label class="field"><span>年龄</span><input v-model.number="form.age" type="number" min="1" max="120" /></label><label class="field"><span>性别</span><input v-model="form.gender" placeholder="未定" /></label><label class="field"><span>难度</span><select v-model="form.difficulty"><option value="story">剧情</option><option value="adventure">冒险</option><option value="hard">艰难</option></select></label></div><div class="choice-grid" aria-label="角色 archetype"><button v-for="item in archetypes" :key="item.id" type="button" :class="{ selected: form.archetype === item.id }" :aria-pressed="form.archetype === item.id" @click="form.archetype = item.id"><span class="choice-mark">{{ form.archetype === item.id ? '●' : '○' }}</span><strong>{{ item.name }}</strong><small>{{ item.text }}</small></button></div></section>
      <section v-else class="form-panel review-panel"><div class="panel-heading"><span class="panel-kicker">FINAL REVIEW</span><h2>确认开局资料</h2></div><div class="review-grid"><div><span>游戏 ID</span><strong>{{ form.gameId }}</strong></div><div><span>世界</span><strong>isekai_grey · 灰境</strong></div><div><span>角色</span><strong>{{ form.characterName }} · {{ archetypes.find(a => a.id === form.archetype)?.name }}</strong></div><div><span>难度</span><strong>{{ difficultyNames[form.difficulty] }}</strong></div><div><span>地点</span><strong>{{ form.location || '由世界决定' }}</strong></div><div><span>区域</span><strong>{{ regions.find(r => r[0] === form.region)?.[1] || '由世界决定' }}</strong></div></div><p class="review-note">准备好了，就从第一步开始。</p></section>
      <div class="form-footer"><p v-if="error" class="form-error" role="alert">{{ error }}</p><div class="form-actions"><button v-if="step > 1" class="quiet-button" type="button" @click="step -= 1">上一步</button><button class="primary-button" type="submit" :disabled="game.loading">{{ game.loading ? '建立中…' : step < 3 ? '继续' : '建立远征' }} <span>→</span></button></div></div>
    </form>
  </section>
</template>
